diff --git a/CHANGELOG.md b/CHANGELOG.md
index 2a8ba6d4d2..48b085419b 100644
--- a/CHANGELOG.md
+++ b/CHANGELOG.md
@@ -13,6 +13,17 @@ block a release again.

 ## Unreleased

+- feat(network): channel payload sender block — app members' channel
+  messages carry `{"text": …, "sender": {"name": …, "id": …}}` (public
+  base64 JSON and keyed fanet1 plaintext alike), so DAP agents can
+  attribute the HUMAN author behind the fa_network relay's hub id. The
+  harness unwraps it tolerantly (raw text passes through), rides the
+  name as `AgentMessage.fromName` through the fabric, and the CLI
+  steering line greets people again: `from Uladzimir (<relay id>) in
+  #channel: hello` instead of `from 3cfaee1aa054fe6e…`. The app falls
+  back to the payload sender for bubble names when the envelope carries
+  none; DMs also name hub peers from the whois cache. Legacy payloads
+  without the block decode exactly as before.
 - feat(gh-1956): reply auto-spill — oversized child `reply` / `agent_message`
   payloads spill to an `agent://` artifact automatically; the parent receives a
   bounded excerpt + pointer + completeness marker with char AND byte counts.
diff --git a/docs/dap.md b/docs/dap.md
index 0e71929363..d7608287b3 100644
--- a/docs/dap.md
+++ b/docs/dap.md
@@ -661,6 +661,25 @@ fa_hub_client with the public-payload fallback (0.2.11+ /
 feat/public-channel-payloads); on older clients inbound public frames
 surface as "undecryptable".

+### Channel payload sender block (human attribution across the relay)
+
+App members write through the fa_network relay: on the hub wire the
+frame's `from` is the RELAY's agent id, so a bare payload leaves the
+human author invisible — agents greet the relay
+("Hello 3cfaee1aa054fe6e!"). Channel payloads therefore carry an
+OPTIONAL sender block next to the text (public base64 JSON and keyed
+fanet1 plaintext alike):
+
+```json
+{"text": "hello", "sender": {"name": "Uladzimir", "id": "<memberId>"}}
+```
+
+Producers embed the block when they know the author's display name
+(the app always does post-join); legacy payloads without it stay valid
+forever. Receivers unwrap it tolerantly (raw text passes through) and
+surface the name as the mail's `fromName` — the CLI steering line
+reads `from Uladzimir (<relay-agent-id>) in #channel: …`.
+
 ### Enrolled hub credentials (the app's DAP tab)

 A bare invite link is enough only on hubs that accept the machine's
diff --git a/flutter_app/lib/network/network_session.dart b/flutter_app/lib/network/network_session.dart
index 85468f7a8e..498c16b17b 100644
--- a/flutter_app/lib/network/network_session.dart
+++ b/flutter_app/lib/network/network_session.dart
@@ -6,6 +6,7 @@
 // parameters cannot be initializing formals in Dart.

 import 'dart:async';
+import 'dart:convert';

 import 'package:flutter/foundation.dart';
 import 'package:uuid/uuid.dart';
@@ -370,9 +371,52 @@ final class NetworkSession extends ChangeNotifier {
     orElse: () => Channel(id: channelId, networkId: networkId, isPublic: false),
   );

+  /// Plaintext shape for channel payloads: the text plus, when the member
+  /// has a display name, the sender block that lets DAP agents attribute
+  /// the HUMAN author (the wire sender of a relayed frame is the relay's
+  /// hub agent id). Legacy consumers read `text` and ignore the rest;
+  /// decoders here accept raw payloads from producers without a name.
+  String _channelPlaintext(String text) {
+    final name = identity.displayName.trim();
+    if (name.isEmpty) return text;
+    return jsonEncode({
+      'text': text,
+      'sender': {'name': name, 'id': identity.id},
+    });
+  }
+
+  /// Unwraps an inbound channel plaintext: app members send the
+  /// `{"text": …, "sender": {…}}` envelope (see [_channelPlaintext]);
+  /// raw text from pure-DAP agents or older producers passes through.
+  ({String text, String? senderName}) _unwrapChannelPlaintext(
+    String plaintext,
+  ) {
+    if (!plaintext.startsWith('{')) return (text: plaintext, senderName: null);
+    try {
+      final decoded = jsonDecode(plaintext);
+      if (decoded is Map && decoded['text'] is String) {
+        final sender = decoded['sender'];
+        final name = sender is Map ? sender['name'] : null;
+        return (
+          text: decoded['text'] as String,
+          senderName: name is String && name.trim().isNotEmpty ? name : null,
+        );
+      }
+    } on Object {
+      // Raw text that happens to start with '{' — fall through.
+    }
+    return (text: plaintext, senderName: null);
+  }
+
   Future<String> _encrypt(Channel channel, String text, String frameId) async {
     // Public showcase channels have no chankey: raw payload by contract.
-    if (channel.isPublic) return encodePublicChannelText(text);
+    if (channel.isPublic) {
+      return encodePublicChannelText(
+        text,
+        senderName: identity.displayName,
+        senderId: identity.id,
